// Generated source files: found mechanically, never classified site by site.
// A LINQ to SQL Database.designer.cs held 3,929 inventory sites that the
// survey could only mark UNKNOWN. Each generated file is still migrated: it is
// translated as ordinary code unless the person chose to regenerate it with
// the target's generator, and a regeneration stays pending until its target
// exists (build approval waits for it).
import fs from 'node:fs';
import path from 'node:path';
import { safePath, filesUnder, writeJSON, lockRun, assertOutputPath, readGeneratedFiles, generatedFilesPath, relativeName, pathMemo } from './core.mjs';

// File names that generators use. GitHub Linguist's generated-file rules
// (lib/linguist/generated.rb, MIT) informed this list.
const namePatterns = [
  [/\.designer\.(?:cs|vb)$/i, 'designer file name'],
  [/\.g\.(?:i\.)?(?:cs|vb)$/i, '.g file name'],
  [/\.pb(?:\.gw)?\.go$/, 'protobuf Go file name'],
  [/\.pb\.(?:cc|h)$/, 'protobuf C++ file name'],
  [/_pb2(?:_grpc)?\.pyi?$/, 'protobuf Python file name'],
  [/\.min\.(?:js|css)$/i, 'minified file name'],
  [/\.generated\.[A-Za-z0-9]+$/i, '.generated file name'],
];
// Markers generators write near the top of the file.
const headerMarkers = [
  [/<auto-generated\b/i, '<auto-generated> header'],
  [/\bCode generated\b.*\bDO NOT EDIT\b/, '"Code generated ... DO NOT EDIT" header'],
  [/@generated\b/, '@generated header'],
  [/\b(?:This|The) (?:file|code|source(?: file)?) (?:was|is|has been) (?:automatically |auto-?)?generated (?:by|from|with|using)\b/i, '"this file was generated" header'],
  [/\bGenerated by (?:the )?(?:protocol buffer compiler|protoc|swig|thrift|antlr|bison|flex|yacc|cython|wsdl|xsd|svcutil|T4|TextTemplatingFileGenerator)\b/i, 'named generator header'],
];
// Inputs a generated file is built from, by the part of its name before the
// generator suffix: Database.designer.cs <- Database.dbml.
const inputExtensions = ['.dbml', '.edmx', '.xsd', '.resx', '.settings', '.tt', '.proto', '.xaml', '.wsdl', '.svcmap', '.datasource', '.aspx', '.ascx', '.master', '.asax', '.asmx', '.js', '.css'];
const headerBytes = 4096;

function header(full) {
  const fd = fs.openSync(full, 'r');
  try { const buffer = Buffer.alloc(headerBytes); return buffer.subarray(0, fs.readSync(fd, buffer, 0, headerBytes, 0)).toString('latin1'); }
  finally { fs.closeSync(fd); }
}
// Minimal .gitattributes glob: *, ** and ?; a pattern without / matches a name at any depth.
const globParts = { '**/': '(?:.*/)?', '/**': '(?:/.*)?', '**': '.*', '*': '[^/]*', '?': '[^/]' };
export function globRegex(pattern) {
  const body = pattern.replace(/^\//, '').replace(/\*\*\/|\/\*\*|\*\*|\*|\?|[.+^${}()|[\]\\]/g, t => globParts[t] ?? `\\${t}`);
  return new RegExp(pattern.replace(/\/$/, '').includes('/') ? `^${body}$` : `(?:^|/)${body}$`);
}
// [regex, generated] per line that sets linguist-generated; the last match wins, as in git.
function linguistGenerated(root) {
  const file = safePath(root, '.gitattributes');
  if (!fs.existsSync(file)) return [];
  const value = attrs => { for (const a of [...attrs].reverse()) {
    if (a === 'linguist-generated' || a === 'linguist-generated=true') return true;
    if (a === '-linguist-generated' || a === '!linguist-generated' || a === 'linguist-generated=false') return false;
  } return null; };
  return fs.readFileSync(file, 'utf8').split(/\r?\n/).map(l => l.trim()).filter(l => l && !l.startsWith('#'))
    .map(l => l.split(/\s+/)).map(([pattern, ...attrs]) => [pattern, value(attrs)]).filter(([, v]) => v !== null)
    .map(([pattern, v]) => [globRegex(pattern), v]);
}
// <None Include="Database.dbml"><Generator>…</Generator><LastGenOutput>Database.designer.cs</LastGenOutput>
// and <Compile Include="X.Designer.cs"><AutoGen>True</AutoGen><DependentUpon>X.resx</DependentUpon>.
function projectDeclarations(root, files) {
  const found = new Map();
  for (const project of files.filter(p => /\.(?:cs|vb|fs)proj$/i.test(p))) {
    const dir = path.posix.dirname(project), text = fs.readFileSync(safePath(root, project), 'utf8');
    const resolve = name => path.posix.normalize(path.posix.join(dir === '.' ? '' : dir, name.replace(/\\/g, '/')));
    // A self-closing <Compile Include="X" /> has no body; never read the next element's.
    for (const m of text.matchAll(/<(\w+)\s+Include="([^"]+)"(?:[^>\/]|\/(?!>))*>([\s\S]*?)<\/\1>/g)) {
      const [, , include, body] = m, last = body.match(/<LastGenOutput>([^<]+)<\/LastGenOutput>/)?.[1];
      if (last) found.set(resolve(path.posix.join(path.posix.dirname(include.replace(/\\/g, '/')), last)), { signal: `${project} LastGenOutput`, input: resolve(include) });
      if (/<AutoGen>\s*true\s*<\/AutoGen>/i.test(body)) {
        const upon = body.match(/<DependentUpon>([^<]+)<\/DependentUpon>/)?.[1];
        found.set(resolve(include), { signal: `${project} AutoGen`, input: upon ? resolve(path.posix.join(path.posix.dirname(include.replace(/\\/g, '/')), upon)) : null });
      }
    }
  }
  return found;
}
function siblingInput(file, all) {
  const base = file.replace(/\.designer\.(?:cs|vb)$/i, '').replace(/\.g\.(?:i\.)?(?:cs|vb)$/i, '').replace(/\.pb(?:\.gw)?\.go$|\.pb\.(?:cc|h)$|_pb2(?:_grpc)?\.pyi?$|\.min\.(?:js|css)$|\.generated\.[A-Za-z0-9]+$/i, '');
  if (base === file) return null;
  if (all.has(base) && base !== file) return base;
  const lower = new Map([...all].map(p => [p.toLowerCase(), p]));
  for (const ext of inputExtensions) { const hit = lower.get(`${base}${ext}`.toLowerCase()); if (hit && hit !== file) return hit; }
  // protoc output often sits away from its .proto: match by name.
  if (/\.pb|_pb2/.test(file)) { const name = `${path.posix.basename(base)}.proto`; return [...all].find(p => path.posix.basename(p) === name) ?? null; }
  return null;
}

export function detectGeneratedFiles(root, config) {
  const memo = pathMemo();
  const files = [...new Set(config.sourceRoots.flatMap(dir => filesUnder(root, dir, memo)))].sort();
  const all = new Set(files), declared = projectDeclarations(root, files), attributes = linguistGenerated(root);
  const out = [];
  for (const file of files) {
    const signals = [];
    for (const [pattern, signal] of namePatterns) if (pattern.test(file)) signals.push(signal);
    try { const text = header(safePath(root, file, memo)); for (const [pattern, signal] of headerMarkers) if (pattern.test(text)) signals.push(signal); } catch {}
    if (declared.has(file)) signals.push(declared.get(file).signal);
    if (attributes.filter(([r]) => r.test(file)).at(-1)?.[1]) signals.push('.gitattributes linguist-generated');
    if (!signals.length) continue;
    const input = declared.get(file)?.input && all.has(declared.get(file).input) ? declared.get(file).input : siblingInput(file, all);
    out.push({ file, signals, input });
  }
  return out;
}

function manifestTargets(root) {
  const file = safePath(root, 'migration/manifest.tsv');
  if (!fs.existsSync(file)) return new Map();
  return new Map(fs.readFileSync(file, 'utf8').replace(/^﻿/, '').split(/\r?\n/).slice(1).filter(Boolean).map(l => l.split('\t')).filter(c => c.length === 2));
}
function writeEntries(root, files) {
  writeJSON(safePath(root, generatedFilesPath), { schemaVersion: 1, note: 'Generated source files. The inventory survey classifies their sites without a model. action translate: ported as ordinary code. action regenerate: produced by the target generator (how), so build approval waits until target exists.', files });
}

// generated-files: detect (preview), --write keeps earlier decisions, then
// --regenerate FILE --how TEXT [--target PATH] or --translate FILE changes one.
export function generatedFilesCommand(root, config, { write = false, regenerate, translate, how, target } = {}) {
  if ([regenerate, translate].filter(Boolean).length > 1) throw new Error('Choose one of --regenerate FILE or --translate FILE');
  const release = write || regenerate || translate ? lockRun(root, 'generated-files') : () => {};
  try {
    const previous = new Map(readGeneratedFiles(root).map(e => [e.file, e]));
    let entries, dropped = [];
    if (write || !previous.size) {
      // A new scan keeps every earlier decision for a file it still finds.
      entries = detectGeneratedFiles(root, config).map(e => {
        const old = previous.get(e.file);
        return old ? { ...e, action: old.action, ...(old.action === 'regenerate' ? { how: old.how, target: old.target, input: old.input } : {}) } : { ...e, action: 'translate' };
      });
      // A regeneration decided for a file no longer detected is reported, not kept silently.
      dropped = [...previous.values()].filter(e => e.action === 'regenerate' && !entries.some(n => n.file === e.file)).map(e => e.file);
    } else entries = [...previous.values()];
    const name = regenerate ?? translate;
    if (name) {
      relativeName(name);
      const entry = entries.find(e => e.file === name);
      if (!entry) throw new Error(`${name} is not a detected generated file; run generated-files --write first`);
      if (translate) { delete entry.how; delete entry.target; entry.action = 'translate'; }
      else {
        if (typeof how !== 'string' || !how.trim()) throw new Error('--regenerate needs --how TEXT: the target generator or command that rebuilds this file');
        if (!entry.input) throw new Error(`${name} has no generator input in the repository, so it cannot be regenerated; it stays translated as ordinary code`);
        const mapped = target ?? manifestTargets(root).get(name);
        if (!mapped) throw new Error(`${name} has no manifest target; pass --target PATH under outputRoots`);
        assertOutputPath(root, config, mapped, name);
        Object.assign(entry, { action: 'regenerate', how: how.trim(), target: mapped });
      }
    }
    if (write || name) writeEntries(root, entries);
    const count = action => entries.filter(e => e.action === action).length;
    return { kind: 'generated-files', file: generatedFilesPath, written: Boolean(write || name), files: entries.length, translate: count('translate'), regenerate: count('regenerate'),
      withoutInput: entries.filter(e => !e.input).map(e => e.file), ...(dropped.length ? { droppedRegenerations: dropped } : {}), entries,
      next: dropped.length ? `${dropped.length} file(s) chosen for regeneration are no longer detected as generated and are translated again (droppedRegenerations); tell the person and record the regeneration again if they still want it.` : entries.length ? 'Generated files are translated as ordinary code by default. Ask how each generator input should be rebuilt in the target with the policy questions; record a regeneration with --regenerate FILE --how TEXT.' : 'No generated files found.' };
  } finally { release(); }
}

// Inventory rows for census sites in generated files, written without a model.
export function generatedRows(root, entries, sites) {
  const byFile = new Map(entries.map(e => [e.file, e])), lines = new Map();
  const count = file => {
    if (!lines.has(file)) { const text = fs.readFileSync(safePath(root, file), 'latin1'); lines.set(file, Math.max(1, text.split(/\r\n|\n|\r/).length - (/(?:\r\n|\n|\r)$/.test(text) ? 1 : 0))); }
    return lines.get(file);
  };
  return sites.filter(s => byFile.has(s.file)).map(site => {
    const e = byFile.get(site.file);
    const translation = e.action === 'regenerate'
      ? `Generated from ${e.input}; regenerate in the target (${e.how.replace(/[\t\r\n]+/g, ' ')}) instead of translating it.`
      : `Generated code${e.input ? ` (input ${e.input})` : ''}: not classified site by site; translate the file as ordinary code under the RULEBOOK, keeping its public types and members.`;
    return { ...site, classification: 'GENERATED', target_translation: translation, status: 'confirmed',
      evidence: `${site.file}:1-${count(site.file)} (generated file: ${e.signals.join(', ').replace(/[\t\r\n]+/g, ' ')})` };
  });
}

// Regenerations whose target does not exist yet.
// The target is checked like any output, so a hand-edited record cannot name the
// source or a protected path and pass as already regenerated.
export function pendingRegeneration(root, config) {
  return readGeneratedFiles(root).filter(e => e.action === 'regenerate' && !fs.existsSync(assertOutputPath(root, config, e.target, e.file))).map(e => ({ file: e.file, input: e.input, how: e.how, target: e.target }));
}
